import{z as p,x as d,o as E,c as A,q as s,j as n,D as l,d as t,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"复制状态机","description":"","frontmatter":{"title":"复制状态机","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/replicated-state-machine.md","filePath":"cs/replicated-state-machine.md","lastUpdated":1791063341000}'),B={name:"cs/replicated-state-machine.md"};function c(m,a,h,u,S,f){const r=d("Mermaid");return E(),A("div",null,[a[2]||(a[2]=s('<h1 id="复制状态机" tabindex="-1">复制状态机 <a class="header-anchor" href="#复制状态机" aria-label="Permalink to &quot;复制状态机&quot;">​</a></h1><div class="epigraph"><p>确定性状态机 + 同一输入日志 ⇒ 同一状态。共识的任务是复制那条日志，不是复制内存字节。</p><footer>—— 据 Schneider, Implementing Fault-Tolerant Services Using the State Machine Approach, CSUR 1990 整理</footer></div><p>上一课<a href="/cs/session-guarantees">会话保证</a>仍允许全局分叉。缺口是<strong>所有客户端看见同一操作序</strong>：锁、配置、事务提交需要这个。本课钉 Schneider 的状态机方法，把前面的线性一致对象还原成「日志上的确定性 apply」。后课 Paxos 才说日志怎么达成。不重写 CRDT 半格。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>副本各自有状态 \\(s\\)，操作 \\(o\\) 是确定性的：\\(s&#39;=\\delta(s,o)\\)。若所有正确副本 apply 同一序列 \\(o_1,o_2,\\ldots\\)，则状态永远相等。故障：崩溃停副本落后，追上日志即可。缺口从「复制状态」变成「复制输入序」——带宽与语义都更干净，因为状态可能很大，操作很小。</p><p>非确定性（时间、随机、线程调度）必须赶出 \\(\\delta\\)：把随机数当输入放进日志，而不是各机自抽。这是实现 RSM 最常见的破法。</p><p><span class="marginnote">Schneider 1990 综述把 Lamport 时间、共识、拜占庭都接到状态机框架。主备传状态是另一方法，上单元已讲。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三件套：共识模块输出已提交前缀；状态机按前缀 apply；客户端把请求交给共识（或领导者）。快照把前缀压缩成状态，截断日志——后课 Raft 快照。读：跟日志提交点走则线性一致；读落后副本则掉档。</p><p><span class="marginnote">数字实例：状态若是 10 GB 的键值表、每秒 500 条操作指令，传状态一次要小时级，而传日志每秒不过几十 KB——「复制输入序」比「复制状态」便宜几个数量级。新副本上线也只需回放日志，不必全量拷贝。</span></p><p><span class="marginnote">常见误区：初学者容易以为「三个副本跑同一份代码」就自动一致。实际上只要 \\(\\delta\\) 里藏了 <code>now()</code>、随机数或读本地时钟，三台机器 apply 同一条指令也会算出不同结果——非确定性不是被容忍的，而是必须被赶出 \\(\\delta\\)、变成日志里的显式输入。</span></p>',11)),(E(),n(i,null,{default:l(()=>[o(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20REQ%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20LOG%5B%22%E5%85%B1%E8%AF%86%E6%97%A5%E5%BF%97%22%5D%0A%20%20LOG%20--%3E%20APP%5B%22%E7%A1%AE%E5%AE%9A%E6%80%A7%20apply%22%5D%0A%20%20APP%20--%3E%20S%5B%22%E5%89%AF%E6%9C%AC%E7%8A%B6%E6%80%81%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与寄存器 quorum：RSM 给的是操作的全序，能实现任意对象，不只是读写寄存器。与 CRDT：RSM 协调贵、语义任意；CRDT 无协调、语义受限。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"线性化点：通常在日志提交（多数派持久）处，apply 必须在返回前完成，或返回的索引对后续读可见。Raft 的 read index、lease read 是优化，不改这一定义。",-1)),a[6]||(a[6]=e("p",null,[t("拜占庭 RSM 要求确定性"),e("strong",null,"且"),t("不能让叛徒提交两条日志——那是 PBFT。崩溃 RSM 用 Paxos/Raft/VR。本课故障类仍默认崩溃停或崩溃恢复（日志在盘上）。")],-1)),(E(),n(i,null,{default:l(()=>[o(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20O%5B%22%E6%8C%87%E4%BB%A4%3A%20SET%20x%3D5%20%E5%90%AB%E6%97%B6%E9%97%B4%E6%88%B37%22%5D%20--%3E%20NQ%7B%22%E6%97%B6%E9%97%B4%E6%88%B3%E4%BB%8E%E5%93%AA%E6%9D%A5%3F%22%7D%0A%20%20NQ%20--%20%22%E5%90%84%E5%89%AF%E6%9C%AC%E8%87%AA%E5%8F%96%20now()%22%20--%3E%20BUG%5B%22%E5%90%8C%E4%B8%80%E6%8C%87%E4%BB%A4%E7%AE%97%E5%87%BA%E4%B8%8D%E5%90%8C%E7%8A%B6%E6%80%81%2C%20%E5%88%86%E5%8F%89%22%5D%0A%20%20NQ%20--%20%22%E6%97%B6%E9%97%B4%E6%88%B3%E4%BD%9C%E4%B8%BA%E6%97%A5%E5%BF%97%E8%BE%93%E5%85%A5%22%20--%3E%20LOG%5B%22%E5%86%99%E5%85%A5%E5%85%B1%E8%AF%86%E6%97%A5%E5%BF%97%22%5D%0A%20%20LOG%20--%3E%20OK%5B%22%E4%B8%89%E5%89%AF%E6%9C%AC%20apply%20%E5%90%8E%E7%8A%B6%E6%80%81%E9%80%90%E5%AD%97%E8%8A%82%E7%9B%B8%E5%90%8C%22%5D%0A%20%20BUG%20-.%E4%BF%AE%E5%A4%8D%E8%B7%AF%E5%BE%84.-%3E%20LOG%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p>这张图回答的问题是「非确定性藏在哪、怎么修」：同一条 <code>SET</code> 指令，若时间戳由各副本现场调用时钟取得，三台机器可能各算各的；把时间戳本身写进日志、当作 \\(\\delta\\) 的显式输入，副本就退化成纯粹的回放器。</p><p><span class="marginnote">为什么重要：这一步如果做错了，副本分叉不会立刻报警——它会在某次读返回旧值、或某次选主后状态跳变时才暴露，且难以复现。上线前的检查办法是审计 \\(\\delta\\) 的每条路径：凡读时钟、随机数、线程 ID 的调用，都必须改成从日志取。</span></p><p>本课不把 Kubernetes 控制器当 RSM 证明：调和循环是最终一致。也不把 WAL 单机恢复当成分布式日志共识。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 prepare/accept 消息，不引入成员变更。后课默认：要线性一致任意对象，用 RSM；日志的共识算法从 Paxos 讲起。主备是状态转移特例，链是提交点特例，都不是任意 \\(\\delta\\) 的通用解。</p><p>输入序是唯一需要共识的东西。状态是推论。下一课开始付共识的消息税。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RSM：同一确定性 \\(\\delta\\) + 同一已提交日志。</li><li>非确定性必须进日志，不能进 \\(\\delta\\)。</li><li>读的一致性档取决于读到哪条提交前缀。</li><li>出处：Schneider, CSUR 1990。</li></ul>',8))])}const _=p(B,[["render",c]]);export{D as __pageData,_ as default};
